import hmac
import hashlib
import base64
import json
import time
import os
import secrets

SECRET_KEY = os.environ.get('SECRET_KEY', secrets.token_hex(32)).encode()


class TokenService:
    """Secure token service for API authentication."""

    def __init__(self, secret_key=SECRET_KEY, algorithm='sha256'):
        self._secret = secret_key
        self._algorithm = algorithm
        self._revoked = set()

    def _encode_segment(self, data: dict) -> bytes:
        """Encode a JSON segment to URL-safe base64."""
        json_bytes = json.dumps(data, separators=(',', ':')).encode('utf-8')
        return base64.urlsafe_b64encode(json_bytes).rstrip(b'=')

    def _decode_segment(self, segment: bytes) -> dict:
        """Decode a URL-safe base64 segment to JSON."""
        # Add padding back
        padding = 4 - len(segment) % 4
        if padding != 4:
            segment += b'=' * padding
        json_bytes = base64.urlsafe_b64decode(segment)
        return json.loads(json_bytes)

    def _compute_signature(self, header_b64: bytes, payload_b64: bytes) -> bytes:
        """Compute HMAC signature over header.payload."""
        signing_input = header_b64 + b'.' + payload_b64
        sig = hmac.new(self._secret, signing_input, hashlib.sha256).digest()
        return base64.urlsafe_b64encode(sig).rstrip(b'=')

    def create_token(self, user_id: str, role: str = 'user', ttl: int = 3600) -> str:
        """Create a signed token."""
        header = {'alg': 'HS256', 'typ': 'JWT'}
        payload = {
            'sub': user_id,
            'role': role,
            'iat': int(time.time()),
            'exp': int(time.time()) + ttl,
            'jti': secrets.token_hex(16)
        }

        header_b64 = self._encode_segment(header)
        payload_b64 = self._encode_segment(payload)
        signature_b64 = self._compute_signature(header_b64, payload_b64)

        return (header_b64 + b'.' + payload_b64 + b'.' + signature_b64).decode('ascii')

    def _verify_signature(self, header_b64: bytes, payload_b64: bytes, signature_b64: bytes) -> bool:
        """Verify the token signature."""
        expected_sig = self._compute_signature(header_b64, payload_b64)
        return hmac.compare_digest(signature_b64, expected_sig)

    def validate_token(self, token: str) -> dict:
        """Validate token and return payload if valid."""
        try:
            parts = token.encode('ascii').split(b'.')
            if len(parts) != 3:
                raise ValueError('Invalid token structure')

            header_b64, payload_b64, signature_b64 = parts

            # Verify header
            header = self._decode_segment(header_b64)
            if header.get('alg') != 'HS256':
                raise ValueError('Unsupported algorithm')

            # Verify signature
            if not self._verify_signature(header_b64, payload_b64, signature_b64):
                raise ValueError('Invalid signature')

            # Decode and verify payload
            payload = self._decode_segment(payload_b64)

            # Check expiration
            if payload.get('exp', 0) < time.time():
                raise ValueError('Token expired')

            # Check revocation
            if payload.get('jti') in self._revoked:
                raise ValueError('Token revoked')

            return payload

        except (ValueError, KeyError, json.JSONDecodeError) as e:
            raise ValueError(f'Token validation failed: {e}')

    def revoke_token(self, token: str):
        """Revoke a token by its JTI."""
        payload = self.validate_token(token)
        self._revoked.add(payload['jti'])


class AuthMiddleware:
    """Middleware for request authentication."""

    ROLE_HIERARCHY = {'admin': 3, 'moderator': 2, 'user': 1, 'guest': 0}

    def __init__(self, token_service: TokenService):
        self._token_service = token_service

    def authenticate(self, request_headers: dict) -> dict:
        """Authenticate a request and return user context."""
        auth_header = request_headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            raise PermissionError('Missing or invalid Authorization header')

        token = auth_header[7:]  # Strip 'Bearer '
        payload = self._token_service.validate_token(token)

        return {
            'user_id': payload['sub'],
            'role': payload['role'],
            'token_id': payload['jti']
        }

    def authorize(self, user_context: dict, required_role: str) -> bool:
        """Check if user has sufficient privileges."""
        user_level = self.ROLE_HIERARCHY.get(user_context.get('role'), 0)
        required_level = self.ROLE_HIERARCHY.get(required_role, 99)
        return user_level >= required_level


# Shared, long-lived service instance so that revocation state (and any other
# in-memory state) persists across requests. Recreating TokenService per call
# would silently reset the revocation set and let revoked tokens authenticate.
_TOKEN_SERVICE = TokenService()
_AUTH_MIDDLEWARE = AuthMiddleware(_TOKEN_SERVICE)


def handle_admin_action(headers: dict, action: str):
    """Handle an admin-only action."""
    middleware = _AUTH_MIDDLEWARE

    user_ctx = middleware.authenticate(headers)

    if not middleware.authorize(user_ctx, 'admin'):
        raise PermissionError(f"User {user_ctx['user_id']} lacks admin privileges")

    return {'status': 'success', 'action': action, 'actor': user_ctx['user_id']}
